// Menu: pause
UINT8 show_menu_pause(void) {
    UINT8 sel = 0u;
    UINT8 joy = 0u;
    move_win(7u, 32u);
    SHOW_WIN;
    _win_print_at(5u, 4u, "Resume", 6u);
    _win_print_at(5u, 5u, "Quit to Title", 13u);
    while (1u) {
        _win_print_at(4u, sel, ">", 1u);
        wait_vbl_done();
        joy = joypad();
        if (joy & J_UP && sel > 0u) {
            _win_print_at(4u, sel, " ", 1u);
            --sel;
            play_sound_step();
        }
        if (joy & J_DOWN && sel < 1u) {
            _win_print_at(4u, sel, " ", 1u);
            ++sel;
            play_sound_step();
        }
        if (joy & J_A) {
            play_sound_door();
            break;
        }
        if (joy & J_B) {
            HIDE_WIN;
            return 255u;
        }
    }
    HIDE_WIN;
    return sel;
}

