// Camera system: camera
void update_camera_camera(void) {
    if (_camera_shake_timer > 0u) {
        UINT8 offset = (_camera_shake_timer & 1u != 0u) ? _camera_shake_intensity : 0u;
        SCX_REG = _camera_x + offset;
        SCY_REG = _camera_y + offset;
        --_camera_shake_timer;
    } else {
        SCX_REG = _camera_x;
        SCY_REG = _camera_y;
    }
}

// Save system: explorer_save (slots=1, checksum=false)
void save_game_explorer_save(UINT8 slotIndex) {
    ENABLE_RAM;
    UINT8* sram = (volatile UINT8 *)(0xA000 + (UINT16)slotIndex * 6u);
    sram[0u] = _hp;
    sram[1u] = _stepCount;
    sram[2u] = _keys;
    sram[3u] = _torchLevel;
    sram[4u] = _level;
    sram[5u] = 171u;
    DISABLE_RAM;
}

void load_game_explorer_save(UINT8 slotIndex) {
    ENABLE_RAM;
    UINT8* sram = (volatile UINT8 *)(0xA000 + (UINT16)slotIndex * 6u);
    if (sram[5u] != 171u) {
        DISABLE_RAM;
        return;
    }
    _hp = sram[0u];
    _stepCount = sram[1u];
    _keys = sram[2u];
    _torchLevel = sram[3u];
    _level = sram[4u];
    DISABLE_RAM;
}

// Exploration system: exploration
void exploration_move_exploration(void) {
    UINT8 nx = _player_x;
    UINT8 ny = _player_y;
    UINT8 direction = 255u;
    if (button_held(J_UP) && ny > 0u) {
        --ny;
        direction = 0u;
    }
    if (button_held(J_DOWN) && ny < 31u) {
        ++ny;
        direction = 1u;
    } else {
        if (button_held(J_LEFT) && nx > 0u) {
            --nx;
            direction = 2u;
        } else {
            if (button_held(J_RIGHT) && nx < 31u) {
                ++nx;
                direction = 3u;
            } else {
                return;
            }
        }
    }
    if (_map_collision(nx, ny)) {
        return;
    }
    UINT8 entity_id = _entity_check(nx, ny);
    if (entity_id != 255u) {
        _entity_handle_block(entity_id, nx, ny, direction);
        if (_entity_collision_mode[entity_id] != 3u) {
            return;
        }
    }
    _player_x = nx;
    _player_y = ny;
    exploration_step_exploration();
}

void exploration_step_exploration(void) {
    ++_exploration_step_count;
    if (_gauge_torch > 0u) {
        _gauge_torch -= 1u;
        if (_gauge_torch <= 50u) {
            navigate_to_scene(SCENE_GAMEPLAY);
        }
        if (_gauge_torch == 0u) {
            navigate_to_scene(SCENE_GAMEOVER);
        }
    }
    navigate_to_scene(SCENE_GAMEPLAY);
    exploration_encounter_check_exploration();
    zone_check_edges_exploration();
}

void exploration_encounter_check_exploration(void) {
    if (_current_zone_safe) {
        return;
    }
    if (_exploration_step_count < _encounter_safe_steps) {
        return;
    }
    UINT8 roll;
    roll = rand() % 30u;
    UINT8 acc = 0u;
    if (roll < acc + 30u) {
        _encounter_triggered = 1u;
        _encounter_id = 0u;
        return;
    }
    acc += 30u;
}

/* Deduplicated: see show_hud_game_hud */

void zone_load_exploration(UINT8 zone_id) {
    _current_zone_id = zone_id;
    if (_current_tileset_id != zone_id) {
        // load tileset for zone
        _current_tileset_id = zone_id;
    }
    switch (zone_id) {
    case 0u:
        SWITCH_ROM(2);
        set_bkg_tiles(0u, 0u, 32u, 128u, _zone_floor1_tiles);
        SWITCH_ROM(1);
        break;
    case 1u:
        SWITCH_ROM(2);
        set_bkg_tiles(0u, 0u, 16u, 128u, _zone_floor2_tiles);
        SWITCH_ROM(1);
        break;
    default:
        break;
    }
    switch (zone_id) {
    case 0u:
        navigate_to_scene(SCENE_GAMEPLAY);
        break;
    default:
        break;
    }
    switch (zone_id) {
    case 0u:
        _current_zone_safe = 0u;
        break;
    case 1u:
        _current_zone_safe = 1u;
        break;
    default:
        _current_zone_safe = 0u;
        break;
    }
}

void zone_transition_exploration(UINT8 target_zone_id, UINT8 edge, UINT8 entry_x, UINT8 entry_y) {
    if (entry_x != 255u) {
        _player_x = entry_x;
        _player_y = entry_y;
    } else {
        switch (edge) {
        case 2u:
            _player_x = 0u;
            break;
        case 3u:
            _player_x = 31u;
            break;
        case 0u:
            _player_y = 31u;
            break;
        case 1u:
            _player_y = 0u;
            break;
        default:
            break;
        }
    }
    zone_load_exploration(target_zone_id);
}

void zone_check_edges_exploration(void) {
    switch (_current_zone_id) {
    case 0u:
        if (_player_x == 31u) {
            zone_transition_exploration(1u, 2u, 0u, 15u);
            return;
        }
        break;
    case 1u:
        if (_player_x == 0u) {
            zone_transition_exploration(0u, 3u, 31u, 15u);
            return;
        }
        break;
    default:
        break;
    }
}

// Entity collision functions: exploration
void _entity_register(UINT8 entity_id, UINT8 tile_x, UINT8 tile_y, UINT8 mode) {
    _entity_tile_x[entity_id] = tile_x;
    _entity_tile_y[entity_id] = tile_y;
    _entity_collision_mode[entity_id] = mode;
    _entity_collision_shape[entity_id] = 0u;
    UINT8 dy = 0u;
    for (dy = 0u; dy < _entity_tiles_high[entity_id]; dy++) {
        UINT8 dx = 0u;
        for (dx = 0u; dx < _entity_tiles_wide[entity_id]; dx++) {
            UINT8 idx = tile_y + dy * 32u + tile_x + dx;
            _entity_grid[idx / 8u] |= 1u << idx % 8u;
        }
    }
    ++_entity_count;
}

void _entity_remove(UINT8 entity_id) {
    UINT8 tx = _entity_tile_x[entity_id];
    UINT8 ty = _entity_tile_y[entity_id];
    UINT8 dy = 0u;
    for (dy = 0u; dy < _entity_tiles_high[entity_id]; dy++) {
        UINT8 dx = 0u;
        for (dx = 0u; dx < _entity_tiles_wide[entity_id]; dx++) {
            UINT8 idx = ty + dy * 32u + tx + dx;
            _entity_grid[idx / 8u] &= ~1u << idx % 8u;
        }
    }
    _entity_collision_mode[entity_id] = 0xFF;
    _entity_tile_x[entity_id] = 0xFF;
    _entity_tile_y[entity_id] = 0xFF;
    --_entity_count;
}

UINT8 _entity_check(UINT8 nx, UINT8 ny) {
    UINT8 idx = ny * 32u + nx;
    UINT8 bit = _entity_grid[idx / 8u] & 1u << idx % 8u;
    if (bit != 0u) {
        UINT8 i = 0u;
        for (i = 0u; i < _entity_count; i++) {
            if (_entity_collision_mode[i] == 0xFF) {
                continue;
            }
            if (_entity_collision_shape[i] == 1u) {
                continue;
            }
            if (_entity_tile_x[i] == nx && _entity_tile_y[i] == ny) {
                return i;
            }
        }
    }
    return 0xFF;
}

void _entity_handle_block(UINT8 entity_id, UINT8 nx, UINT8 ny, UINT8 direction) {
    switch (_entity_collision_mode[entity_id]) {
    case 0u:
        // BLOCK: stop movement, emit bump feedback
        _entity_bump_feedback();
        break;
    case 1u:
        break;
    case 2u:
        // BLOCK_AND_TRIGGER: set _blocking_entity_id before callback (Gap 1)
        _blocking_entity_id = entity_id;
        _entity_bump_feedback();
        navigate_to_scene(SCENE_GAMEPLAY);
        break;
    case 3u:
        // OVERLAP_TRIGGER: allow movement, fire overlap callback
        break;
    case 4u:
        // PUSH: try to move entity, set _pushed_entity_id/_push_direction (Gap 1)
        UINT8 push_dir = _entity_push_dir[entity_id];
        if (push_dir == 1u) {
            if (direction == 0u || direction == 1u) {
                _entity_bump_feedback();
                break;
            }
        }
        if (push_dir == 2u) {
            if (direction == 2u || direction == 3u) {
                _entity_bump_feedback();
                break;
            }
        }
        if (push_dir == 3u) {
            if (!_entity_push_allowed[entity_id] & 1u << direction) {
                _entity_bump_feedback();
                break;
            }
        }
        UINT8 ptx = _entity_tile_x[entity_id];
        UINT8 pty = _entity_tile_y[entity_id];
        switch (direction) {
        case 0u:
            --pty;
            break;
        case 1u:
            ++pty;
            break;
        case 2u:
            --ptx;
            break;
        case 3u:
            ++ptx;
            break;
        default:
            break;
        }
        if (!_map_collision(ptx, pty) && _entity_check(ptx, pty) == 0xFF) {
            _entity_remove(entity_id);
            _entity_register(entity_id, ptx, pty, _entity_collision_mode[entity_id]);
            _pushed_entity_id = entity_id;
            _push_direction = direction;
        } else {
            _entity_bump_feedback();
        }
        break;
    default:
        break;
    }
}

void _entity_set_collision_mode(UINT8 entity_id, UINT8 mode) {
    _entity_collision_mode[entity_id] = mode;
}

