// Scene navigation
void navigate_to_scene(UINT8 scene) {
    switch (current_scene) {
    case SCENE_GAMEPLAY:
        gameplay_exit_trampoline();
        break;
    }
    current_scene = scene;
    switch (scene) {
    case SCENE_GAMEOVER:
        gameover_enter_trampoline();
        break;
    case SCENE_COMBAT_SCENE:
        combat_scene_enter_trampoline();
        break;
    case SCENE_PAUSE:
        pause_enter_trampoline();
        break;
    case SCENE_GAMEPLAY:
        gameplay_enter_trampoline();
        break;
    case SCENE_TITLE:
        title_enter_trampoline();
        break;
    }
}

// Entry point
void main(void) {
    NR52_REG = 128u;
    NR50_REG = 119u;
    NR51_REG = 255u;
    DISPLAY_ON;
    SHOW_BKG;
    SHOW_SPRITES;
    set_sprite_data(0u, 2u, sprites_player_tiles);
    set_sprite_tile(0u, 0u);
    move_sprite(0u, _player_x + 8u, _player_y + 16u);
    set_sprite_tile(1u, 1u);
    move_sprite(1u, _player_x + 8u, _player_y + 24u);
    title_enter_trampoline();
    while (1) {
        update_joypad();
        switch (current_scene) {
        case SCENE_GAMEOVER:
            gameover_frame_trampoline();
            break;
        case SCENE_COMBAT_SCENE:
            combat_scene_frame_trampoline();
            break;
        case SCENE_PAUSE:
            pause_frame_trampoline();
            break;
        case SCENE_GAMEPLAY:
            gameplay_frame_trampoline();
            break;
        case SCENE_TITLE:
            title_frame_trampoline();
            break;
        }
        update_sprites();
        sound_driver_update();
        wait_vbl_done();
    }
    return;
}
